window.DEMO_SEGMENTS = [{"id": "s0", "time": 0, "page": 1, "topic": "课程导入", "en": "Today we are going to connect probability distributions with information. Keep one question in mind: how uncertain are we before observing the outcome of a random variable?", "zh": "今天我们把概率分布与信息联系起来。先记住一个问题：在观察随机变量的结果之前，我们有多不确定？"}, {"id": "s1", "time": 12.73, "page": 2, "topic": "概率分布", "en": "A probability distribution assigns a probability to every possible outcome. The probabilities are non-negative and they add up to one. Notice that the shape of the distribution tells us how predictable the outcome is.", "zh": "概率分布为每种可能的结果分配概率。各概率非负，且总和为 1。分布的形状告诉我们结果有多容易预测。"}, {"id": "s2", "time": 28.52, "page": 3, "topic": "信息熵", "en": "We measure this uncertainty using Shannon entropy. For a discrete random variable X, entropy is minus the sum of p of x times log base two of p of x. We use base two, so the unit is bits.", "zh": "我们用香农熵来衡量这种不确定性。离散随机变量 X 的熵是 −Σ p(x) log₂ p(x)。以 2 为对数底，单位就是比特。"}, {"id": "s3", "time": 45.15, "page": 3, "topic": "信息熵", "en": "For a fair coin, both outcomes have probability one half, and entropy is one bit. For a coin that always lands heads, entropy is zero. There is no uncertainty because the outcome is already known.", "zh": "公平硬币的两种结果概率均为 1/2，熵为 1 比特。若硬币必定正面朝上，熵为 0，因为结果已知，不存在不确定性。", "key": true}, {"id": "s4", "time": 61.84, "page": 4, "topic": "分布与不确定性", "en": "Compare the two probability distributions on the slide. On the left, the mass is spread evenly. On the right, most of the mass is concentrated in one outcome. For the same finite set of possible outcomes, the uniform distribution has the highest entropy.", "zh": "比较课件上的两种概率分布：左侧概率均匀分散，右侧大部分概率集中在一个结果上。对于相同的有限结果集合，均匀分布的熵最高。", "key": true}, {"id": "s5", "time": 82.43, "page": 5, "topic": "聚类", "en": "Now let us move to clustering. Clustering is an unsupervised learning technique: we group similar observations without using predefined class labels. Think of grouping nearby locations on a map. Our choice of distance changes what similar means.", "zh": "接下来看聚类。聚类是一种无监督学习方法：不依赖预先给定的类别标签，将相似的观测分组。可以想象把地图上相近的地点归组；距离的选取会改变“相似”的含义。"}, {"id": "s6", "time": 101.72, "page": 5, "topic": "聚类", "en": "A good clustering typically has small distances within a group and large distances between groups. In geographical data, scale and coordinate systems matter. Do not apply a distance measure blindly before understanding your data.", "zh": "好的聚类通常组内距离小、组间距离大。处理地理数据时，尺度和坐标系很重要。理解数据之后，再选择合适的距离度量。", "key": true}, {"id": "s7", "time": 118.93, "page": 6, "topic": "复习与练习", "en": "After class, calculate entropy for a fair coin and for a biased coin with probabilities zero point nine and zero point one. Then sketch two clusters and explain which points are similar under your chosen distance measure.", "zh": "课后请分别计算公平硬币和概率为 0.9、0.1 的偏置硬币的熵；再画出两个簇，说明在所选距离度量下，哪些点是相似的。"}];
